texts = {p: (ROOT / p).read_text() for p in CONTRACT["allowed_formal_write_paths"]}
changes = []


def change(path, ids, clause, old, new):
    assert path in texts
    assert texts[path].count(old) == 1, (path, clause, texts[path].count(old))
    texts[path] = texts[path].replace(old, new, 1)
    changes.append({"path": path, "finding_ids": ["GIR-FD82-" + i for i in ids], "clause": clause, "before_text": old, "after_text": new})


def original(clause):
    return next(c["intended_after_text"] for f in MANIFEST["files"] for c in f["clauses"] if c["clause"] == clause)


